from pathlib import Path

root = Path('source/frontend-react/src')

def replace_once(path: Path, old: str, new: str, label: str):
    text = path.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'{label}: marker missing in {path}')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')

# --- auth runtime parity ---
auth = root / 'lib/auth.ts'
s = auth.read_text(encoding='utf-8')

insert_after = '''async function userStatus(user: User) {\n  try {\n    const { db, firestore: f } = await firestoreServices();\n    const snapshot = await f.getDoc(f.doc(db, "users", user.uid));\n    return snapshot.exists() ? String(snapshot.data().status || "active") : "active";\n  } catch {\n    return "active";\n  }\n}\n'''
helper = '''\nexport type AuthResult = {\n  user: User;\n  verificationError?: unknown;\n  profileError?: unknown;\n  emailQueueError?: unknown;\n};\n\nexport async function queueUserEmailEvent(user: User, type: "welcome" | "unsubscribe") {\n  const { db, firestore: f } = await firestoreServices();\n  const id = `${type}_${user.uid}`;\n  await f.setDoc(f.doc(db, "emailEvents", id), {\n    type, sourceCollection: "users", sourceId: user.uid, actorUid: user.uid, createdAt: f.serverTimestamp(),\n  });\n  return id;\n}\n\nexport async function auditEvent(event: "account_created" | "login_password" | "login_google" | "password_changed" | "logout", resourceId = "") {\n  try {\n    const user = await currentUser();\n    if (!user) return;\n    const { db, firestore: f } = await firestoreServices();\n    const write = f.addDoc(f.collection(db, "auditLogs"), {\n      actorUid: user.uid, event, resourceId: String(resourceId).slice(0, 160), source: "web-client", createdAt: f.serverTimestamp(),\n    });\n    await Promise.race([write, new Promise((resolve) => setTimeout(resolve, 1500))]);\n  } catch {\n    console.warn("Registro attività non disponibile. Operazione principale completata.");\n  }\n}\n'''
if 'export type AuthResult' not in s:
    if insert_after not in s:
        raise SystemExit('auth helper insertion marker missing')
    s = s.replace(insert_after, insert_after + helper, 1)

old_ensure = '''export async function ensureUserDoc(user: User, extra: Record<string, unknown> = {}) {\n  const { db, firestore: f } = await firestoreServices();\n  const ref = f.doc(db, "users", user.uid);\n  const snapshot = await f.getDoc(ref);\n  const allowed = new Set(["firstName", "lastName", "phone", "marketingConsent", "termsAcceptedAt", "termsVersion"]);\n  const payload = Object.fromEntries(Object.entries(extra).filter(([key]) => allowed.has(key)));\n\n  if (!snapshot.exists()) {\n    Object.assign(payload, {\n      uid: user.uid,\n      email: user.email || "",\n      displayName: user.displayName || "",\n      marketingConsent: extra.marketingConsent === true,\n      role: "USER",\n      status: "active",\n      createdAt: f.serverTimestamp(),\n    });\n  } else {\n    const current = snapshot.data();\n    if (current.email !== (user.email || "")) payload.email = user.email || "";\n    if (current.displayName !== (user.displayName || "")) payload.displayName = user.displayName || "";\n  }\n\n  if (Object.keys(payload).length) {\n    await f.setDoc(ref, { ...payload, updatedAt: f.serverTimestamp() }, { merge: true });\n  }\n}\n'''
new_ensure = '''export async function ensureUserDoc(user: User, extra: Record<string, unknown> = {}) {\n  const { db, firestore: f } = await firestoreServices();\n  const ref = f.doc(db, "users", user.uid);\n  const snapshot = await f.getDoc(ref);\n  const allowed = new Set(["firstName", "lastName", "phone", "marketingConsent", "termsAcceptedAt", "termsVersion"]);\n  const payload = Object.fromEntries(Object.entries(extra).filter(([key]) => allowed.has(key)));\n  let queueUnsubscribe = false;\n\n  if (!snapshot.exists()) {\n    Object.assign(payload, {\n      uid: user.uid, email: user.email || "", displayName: user.displayName || "",\n      marketingConsent: extra.marketingConsent === true, role: "USER", status: "active", createdAt: f.serverTimestamp(),\n    });\n  } else {\n    const current = snapshot.data();\n    if (current.email !== (user.email || "")) payload.email = user.email || "";\n    if (current.displayName !== (user.displayName || "")) payload.displayName = user.displayName || "";\n    queueUnsubscribe = current.marketingConsent === true && payload.marketingConsent === false;\n  }\n\n  if (Object.keys(payload).length) await f.setDoc(ref, { ...payload, updatedAt: f.serverTimestamp() }, { merge: true });\n  if (queueUnsubscribe) void queueUserEmailEvent(user, "unsubscribe").catch(() => console.warn("Coda unsubscribe non disponibile."));\n}\n'''
if old_ensure not in s:
    raise SystemExit('ensureUserDoc marker missing')
s = s.replace(old_ensure, new_ensure, 1)

start = s.index('export async function loginEmail(')
end = s.index('\nexport async function logout()', start)
new_auth_flows = '''export async function loginEmail(email: string, password: string): Promise<AuthResult> {\n  const { auth, sdk } = await authServices();\n  const result = await sdk.signInWithEmailAndPassword(auth, email.trim(), password);\n  const user = await requireActiveUser(result.user);\n  let profileError: unknown;\n  try { await ensureUserDoc(user); } catch (error) { profileError = error; }\n  void auditEvent("login_password");\n  return { user, profileError };\n}\n\nexport async function registerEmail(data: {\n  email: string; password: string; firstName: string; lastName: string; termsConsent: boolean; marketingConsent?: boolean;\n}): Promise<AuthResult> {\n  if (!data.termsConsent) throw new Error("TERMS_REQUIRED");\n  if (data.password.length < 8) throw new Error("auth/weak-password");\n  const { auth, sdk } = await authServices();\n  const result = await sdk.createUserWithEmailAndPassword(auth, data.email.trim(), data.password);\n  const user = result.user;\n  const displayName = `${data.firstName} ${data.lastName}`.trim();\n  let profileError: unknown;\n  let verificationError: unknown;\n  let emailQueueError: unknown;\n  try {\n    if (displayName) await sdk.updateProfile(user, { displayName });\n    await ensureUserDoc(user, {\n      firstName: data.firstName, lastName: data.lastName, marketingConsent: data.marketingConsent === true,\n      termsAcceptedAt: new Date().toISOString(), termsVersion: "2026-09-01",\n    });\n  } catch (error) { profileError = error; }\n  if (!user.emailVerified) {\n    try {\n      const language = languageFromPath();\n      await sdk.sendEmailVerification(user, { url: `${location.origin}${withLanguage("/profilo?verified=1", language)}`, handleCodeInApp: false });\n    } catch (error) { verificationError = error; }\n  }\n  if (!profileError) {\n    try { await queueUserEmailEvent(user, "welcome"); } catch (error) { emailQueueError = error; }\n  }\n  void auditEvent("account_created");\n  return { user, verificationError, profileError, emailQueueError };\n}\n\nexport async function loginGoogle(extra: Record<string, unknown> = {}): Promise<AuthResult> {\n  const { auth, sdk } = await authServices();\n  const provider = new sdk.GoogleAuthProvider();\n  provider.setCustomParameters({ prompt: "select_account" });\n  const result = await sdk.signInWithPopup(auth, provider);\n  const user = await requireActiveUser(result.user);\n  let profileError: unknown;\n  let emailQueueError: unknown;\n  try { await ensureUserDoc(user, extra); } catch (error) { profileError = error; }\n  const info = typeof sdk.getAdditionalUserInfo === "function" ? sdk.getAdditionalUserInfo(result) : null;\n  if (!profileError && info?.isNewUser) {\n    try { await queueUserEmailEvent(user, "welcome"); } catch (error) { emailQueueError = error; }\n  }\n  void auditEvent("login_google");\n  return { user, profileError, emailQueueError };\n}\n\nexport async function refreshVerification() {\n  const user = await currentUser();\n  if (!user) throw new Error("AUTH_REQUIRED");\n  await user.reload();\n  await user.getIdToken(true);\n  return user;\n}\n'''
s = s[:start] + new_auth_flows + s[end:]

old_logout = '''export async function logout() {\n  const { auth, sdk } = await authServices();\n  await sdk.signOut(auth);\n}\n'''
new_logout = '''export async function logout() {\n  const audit = auditEvent("logout");\n  const { auth, sdk } = await authServices();\n  await sdk.signOut(auth);\n  void audit;\n}\n'''
if old_logout not in s:
    raise SystemExit('logout marker missing')
s = s.replace(old_logout, new_logout, 1)
auth.write_text(s, encoding='utf-8')

# --- AuthPage finish flow parity ---
p = root / 'pages/AuthPage.tsx'
s = p.read_text(encoding='utf-8')
s = s.replace('import { authErrorMessage, loginEmail, loginGoogle, registerEmail, resetPassword } from "../lib/auth";', 'import { authErrorMessage, loginEmail, loginGoogle, registerEmail, resetPassword, type AuthResult } from "../lib/auth";')
marker = '''  useEffect(() => {\n    const title = mode === "login" ? copy.login : copy.register;\n    setPageSeo({ title: `${title} | CalabriaVera`, description: mode === "login" ? copy.loginText : copy.registerText, path: mode === "login" ? "/login" : "/registrazione", robots: "noindex,follow" });\n  }, [mode, language, copy.login, copy.register, copy.loginText, copy.registerText]);\n'''
finish = '''\n  const finish = (result: AuthResult, created = false) => {\n    const params = new URLSearchParams();\n    if (created) params.set("created", "1");\n    if (result.verificationError) params.set("verification", "failed");\n    if (result.profileError) params.set("profile", "failed");\n    if (result.emailQueueError) params.set("welcome", "queued-failed");\n    if (!result.user.emailVerified || created || result.profileError || result.emailQueueError) {\n      if (!/\\/profilo(?:[?#]|$)/.test(next)) params.set("next", next);\n      const query = params.toString();\n      navigate(withLanguage(`/profilo${query ? `?${query}` : ""}`, language), true);\n    } else navigate(next, true);\n  };\n'''
if marker not in s:
    raise SystemExit('AuthPage effect marker missing')
s = s.replace(marker, marker + finish, 1)
s = s.replace('''        await loginEmail(String(data.get("email") || ""), String(data.get("password") || ""));\n        navigate(next, true);''', '''        finish(await loginEmail(String(data.get("email") || ""), String(data.get("password") || "")));''', 1)
s = s.replace('''        await registerEmail({ email: String(data.get("email") || ""), password, firstName: String(data.get("firstName") || ""), lastName: String(data.get("lastName") || ""), termsConsent: data.get("termsConsent") === "on", marketingConsent: data.get("marketingConsent") === "on" });\n        setMessage(copy.created); form.reset();''', '''        finish(await registerEmail({ email: String(data.get("email") || ""), password, firstName: String(data.get("firstName") || ""), lastName: String(data.get("lastName") || ""), termsConsent: data.get("termsConsent") === "on", marketingConsent: data.get("marketingConsent") === "on" }), true);''', 1)
s = s.replace('''      await loginGoogle(mode === "register" ? { marketingConsent: marketing?.checked === true, termsAcceptedAt: new Date().toISOString(), termsVersion: "2026-09-01" } : {});\n      navigate(next, true);''', '''      finish(await loginGoogle(mode === "register" ? { marketingConsent: marketing?.checked === true, termsAcceptedAt: new Date().toISOString(), termsVersion: "2026-09-01" } : {}));''', 1)
p.write_text(s, encoding='utf-8')

# --- account helpers / analytics / role parity ---
p = root / 'lib/account.ts'
s = p.read_text(encoding='utf-8')
s = s.replace('import { currentUser, requireActiveUser } from "./auth";', 'import { auditEvent, currentUser, queueUserEmailEvent, requireActiveUser } from "./auth";')
old = '''  const snapshot = await f.getDoc(f.doc(db, "users", user.uid));\n  return {\n    uid: user.uid,\n    email: user.email || "",\n    displayName: user.displayName || "",\n    emailVerified: user.emailVerified,\n    passwordAccount: user.providerData.some((provider) => provider.providerId === "password"),\n    ...(snapshot.exists() ? snapshot.data() : {}),\n  } as Record<string, unknown> & { uid: string; email: string; displayName: string; emailVerified: boolean; passwordAccount: boolean };'''
new = '''  const snapshot = await f.getDoc(f.doc(db, "users", user.uid));\n  const data = snapshot.exists() ? snapshot.data() : {};\n  const token = await user.getIdTokenResult().catch(() => null);\n  const isAdmin = token?.claims.admin === true;\n  const roleLabel = isAdmin ? "Amministratore" : data.role === "OWNER" ? "Proprietario" : "Utente";\n  return {\n    ...data, uid: user.uid, email: user.email || "", displayName: user.displayName || "", emailVerified: user.emailVerified,\n    passwordAccount: user.providerData.some((provider) => provider.providerId === "password"), isAdmin, roleLabel,\n  } as Record<string, unknown> & { uid: string; email: string; displayName: string; emailVerified: boolean; passwordAccount: boolean; isAdmin: boolean; roleLabel: string };'''
if old not in s:
    raise SystemExit('loadProfile return marker missing')
s = s.replace(old, new, 1)
old_save = '''  const userRef = firestore.doc(db, "users", user.uid);\n  await Promise.all([\n    firestore.setDoc(userRef, { ...patch, displayName, email: user.email || "", updatedAt: firestore.serverTimestamp() }, { merge: true }),\n    displayName && displayName !== user.displayName ? authSdk.updateProfile(user, { displayName }) : Promise.resolve(),\n  ]);'''
new_save = '''  const userRef = firestore.doc(db, "users", user.uid);\n  const before = await firestore.getDoc(userRef).catch(() => null);\n  const queueUnsubscribe = Boolean(before?.exists() && before.data().marketingConsent === true && patch.marketingConsent === false);\n  await Promise.all([\n    firestore.setDoc(userRef, { ...patch, displayName, email: user.email || "", updatedAt: firestore.serverTimestamp() }, { merge: true }),\n    displayName && displayName !== user.displayName ? authSdk.updateProfile(user, { displayName }) : Promise.resolve(),\n  ]);\n  if (queueUnsubscribe) void queueUserEmailEvent(user, "unsubscribe").catch(() => undefined);'''
if old_save not in s:
    raise SystemExit('saveProfile marker missing')
s = s.replace(old_save, new_save, 1)
old_pw = '''  await authSdk.reauthenticateWithCredential(user, credential);\n  await authSdk.updatePassword(user, newPassword);\n}'''
new_pw = '''  await authSdk.reauthenticateWithCredential(user, credential);\n  await authSdk.updatePassword(user, newPassword);\n  void auditEvent("password_changed");\n}'''
if old_pw not in s:
    raise SystemExit('change password marker missing')
s = s.replace(old_pw, new_pw, 1)
p.write_text(s, encoding='utf-8')

# --- Profile UI / verification parity ---
p = root / 'pages/ProfilePage.tsx'
s = p.read_text(encoding='utf-8')
s = s.replace('import { logout } from "../lib/auth";', 'import { logout, refreshVerification } from "../lib/auth";')
s = s.replace('''  const [passwordBusy, setPasswordBusy] = useState(false);\n  const [message, setMessage] = useState("");''', '''  const [passwordBusy, setPasswordBusy] = useState(false);\n  const [verificationBusy, setVerificationBusy] = useState(false);\n  const [message, setMessage] = useState("");''', 1)
marker = '''  const resend = async () => {\n    setBusy(true); setMessage(""); setError("");\n    try {\n      const sent = await resendVerificationEmail();\n      const latest = await refresh();\n      setMessage(sent ? copy.sent : latest.emailVerified ? copy.already : copy.sent);\n    } catch { setError(copy.saveError); }\n    finally { setBusy(false); }\n  };\n'''
extra = '''\n  const checkVerification = async () => {\n    setVerificationBusy(true); setMessage(""); setError("");\n    try {\n      const user = await refreshVerification();\n      await refresh();\n      setMessage(user.emailVerified ? "Verifica completata." : "Email non ancora verificata.");\n    } catch { setError(copy.saveError); }\n    finally { setVerificationBusy(false); }\n  };\n'''
if marker not in s:
    raise SystemExit('profile resend marker missing')
s = s.replace(marker, marker + extra, 1)

marker = '''  const avatarUrl = profile ? String(profile.avatarDataUrl || "") : "";\n  const initials = profile ? String(profile.firstName || profile.displayName || profile.email || "U").trim().charAt(0).toUpperCase() : "U";\n'''
extra = '''  const params = new URLSearchParams(location.search);\n  const requestedNext = params.get("next") || withLanguage("/dashboard", language);\n  const next = requestedNext.startsWith("/") && !requestedNext.startsWith("//") ? requestedNext : withLanguage("/dashboard", language);\n'''
if marker not in s:
    raise SystemExit('profile computed marker missing')
s = s.replace(marker, marker + extra, 1)

s = s.replace('''      {message ? <div className="mt-6 rounded-xl bg-emerald-50 p-4 font-bold text-emerald-800">{message}</div> : null}\n      {profile ? <div className="mt-8 grid gap-6 md:grid-cols-[1fr_300px]">''', '''      {message ? <div className="mt-6 rounded-xl bg-emerald-50 p-4 font-bold text-emerald-800">{message}</div> : null}\n      {params.has("created") ? <div className="notice" role="status"><strong>Account creato.</strong><p>{params.get("verification") === "failed" ? "L’email di verifica non è stata inviata. Usa il pulsante Reinvia email." : "Ti abbiamo inviato una email di verifica. Controlla anche lo spam."}</p></div> : null}\n      {params.get("profile") === "failed" ? <div className="notice" role="alert">L’account è attivo, ma il profilo non è disponibile. Ricarica per riprovare.</div> : null}\n      {profile ? <div className="mt-8 grid gap-6 md:grid-cols-[1fr_300px]">''', 1)

old_aside = '''        <aside className="h-fit rounded-[1.7rem] border border-stone-200 bg-white p-6 md:sticky md:top-24">\n          <h2 className="font-black">{copy.status}</h2>\n          <p className="mt-3 text-sm text-stone-600">Email: <strong className={profile.emailVerified ? "text-emerald-700" : "text-amber-700"}>{profile.emailVerified ? copy.verified : copy.unverified}</strong></p>\n          {!profile.emailVerified ? <button type="button" disabled={busy} onClick={() => void resend()} className="mt-3 w-full rounded-xl border border-amber-300 bg-amber-50 px-4 py-3 text-sm font-black text-amber-900 disabled:opacity-50">{copy.resend}</button> : null}\n          <div className="mt-5 grid gap-2"><button type="button" onClick={() => navigate(withLanguage("/preferiti", language))} className="rounded-xl border border-stone-300 px-4 py-3 text-sm font-black">{copy.favorites}</button><button type="button" onClick={() => navigate(withLanguage("/dashboard", language))} className="rounded-xl border border-stone-300 px-4 py-3 text-sm font-black">{copy.businesses}</button><button type="button" onClick={async () => { await logout(); navigate(withLanguage("/", language), true); }} className="rounded-xl border border-red-200 px-4 py-3 text-sm font-black text-red-700">{copy.logout}</button></div>\n        </aside>'''
new_aside = '''        <aside className="h-fit rounded-[1.7rem] border border-stone-200 bg-white p-6 md:sticky md:top-24">\n          <p className="eyebrow">Account</p><h2 className="font-black">{String(profile.displayName || profile.email || "Account")}</h2>\n          <div className="stack">\n            <div><span className="muted">Ruolo</span><br/><strong>{String(profile.roleLabel || "Utente")}</strong></div>\n            <div><span className="muted">Verifica email</span><br/><strong>{profile.emailVerified ? "Email verificata" : "Da verificare"}</strong></div>\n            {!profile.emailVerified ? <div className="stack"><p>Apri il link ricevuto via email, poi premi “Ho verificato l’email”.</p><button type="button" disabled={busy || verificationBusy} onClick={() => void resend()} className="button button-secondary">Reinvia email di verifica</button><button type="button" disabled={verificationBusy} onClick={() => void checkVerification()} className="button button-primary">Ho verificato l’email</button></div> : <button type="button" onClick={() => navigate(next)} className="button button-primary">Continua</button>}\n            <button type="button" onClick={() => navigate(withLanguage("/preferiti", language))} className="button button-secondary">I miei preferiti</button>\n            <button type="button" onClick={() => navigate(withLanguage("/messaggi", language))} className="button button-secondary">I miei messaggi</button>\n            {profile.isAdmin === true ? <button type="button" onClick={() => navigate("/admin")} className="button button-secondary">Amministrazione</button> : null}\n            <button type="button" onClick={async () => { await logout(); navigate(withLanguage("/", language), true); }} className="button button-secondary">Esci dall’account</button>\n          </div>\n        </aside>'''
if old_aside not in s:
    raise SystemExit('profile aside marker missing')
s = s.replace(old_aside, new_aside, 1)
p.write_text(s, encoding='utf-8')

print('React account runtime/profile parity patch applied')
